async def act(page):
    import asyncio

    async def try_close_overlay_once():
        """Attempt a few safe, accessibility-role-centric strategies to close a visible
        overlay, dialog or popup. Returns True if an action likely closed an overlay,
        False otherwise.
        """
        # 1) Try to close role="dialog" elements using named buttons inside them.
        try:
            dialogs = page.get_by_role("dialog")
            dialog_count = await dialogs.count()
        except Exception:
            dialog_count = 0

        for i in range(dialog_count):
            dlg = dialogs.nth(i)
            close_names = ["close", "dismiss", "ok", "×", "x", "✕", "close popup", "dismiss popup"]
            for name in close_names:
                try:
                    btn = dlg.get_by_role("button", name=name)
                    bcnt = await btn.count()
                except Exception:
                    bcnt = 0
                if bcnt > 0:
                    try:
                        await btn.nth(0).click()
                        await asyncio.sleep(0.3)
                        return True
                    except Exception:
                        pass

            # Fallback: click the first button inside the dialog
            try:
                first_btns = dlg.get_by_role("button")
                fb_cnt = await first_btns.count()
            except Exception:
                fb_cnt = 0
            if fb_cnt > 0:
                try:
                    await first_btns.nth(0).click()
                    await asyncio.sleep(0.3)
                    return True
                except Exception:
                    pass

        # 2) Try global role="button" elements whose aria-label/title/text suggests closing
        try:
            all_buttons = page.get_by_role("button")
            btn_count = await all_buttons.count()
        except Exception:
            btn_count = 0

        for i in range(btn_count):
            try:
                btn = all_buttons.nth(i)
                aria = await btn.get_attribute("aria-label")
                title = await btn.get_attribute("title")
                txt = await btn.inner_text()
            except Exception:
                aria = title = txt = None

            aria_l = aria.lower() if isinstance(aria, str) else ""
            title_l = title.lower() if isinstance(title, str) else ""
            txt_l = txt.strip().lower() if isinstance(txt, str) else ""

            if ("close" in aria_l) or ("close" in title_l) or ("close" in txt_l) or (txt.strip() in ["×", "x", "X", "✕"]):
                try:
                    await btn.click()
                    await asyncio.sleep(0.3)
                    return True
                except Exception:
                    pass

        # 3) Try a role="button" with name containing 'dismiss' (substring match is supported)
        try:
            candidate = page.get_by_role("button", name="dismiss")
            if await candidate.count() > 0:
                try:
                    await candidate.nth(0).click()
                    await asyncio.sleep(0.3)
                    return True
                except Exception:
                    pass
        except Exception:
            pass

        # 4) Last-resort CSS-based fallbacks for common close affordances
        try:
            cand = page.locator('[aria-label*="close" i],[title*="close" i],.close,button.close')
            if await cand.count() > 0:
                try:
                    await cand.nth(0).click()
                    await asyncio.sleep(0.3)
                    return True
                except Exception:
                    pass
        except Exception:
            pass

        return False

    # Attempt to dismiss any overlay present in the current page state before calling the helper.
    await try_close_overlay_once()

    # Use the site-aware helper to perform the visible search for "crypto".
    # This helper is required by the instructions (use the knowledge-base function when it exists).
    results = await create_curated_collection_by_search(page, "crypto", max_results=0, resolve_links=True)

    # If the helper returned no results (common when an overlay blocked the complementary region),
    # try to dismiss overlays and retry once.
    if not results:
        await try_close_overlay_once()
        results = await create_curated_collection_by_search(page, "crypto", max_results=0, resolve_links=True)

    # Per the instructions: print the raw API/helper results exactly as received.
    print(results)

    # After the search helper runs, attempt to click the third-to-last result shown in role="main".
    try:
        main = page.get_by_role("main")
        articles = main.get_by_role("article")
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count < 3:
        raise Exception(f"Not enough search results to click the third-to-last (found {article_count}).")

    target_index = article_count - 3
    target_article = articles.nth(target_index)

    # Prefer clicking a link inside the article.
    try:
        links = target_article.get_by_role("link")
        link_count = await links.count()
    except Exception:
        link_count = 0

    if link_count > 0:
        await links.nth(0).click()
        return

    # Fallback: click a heading inside the article
    try:
        headings = target_article.get_by_role("heading")
        heading_count = await headings.count()
    except Exception:
        heading_count = 0

    if heading_count > 0:
        await headings.nth(0).click()
        return

    # Final fallback: click the article container itself.
    await target_article.click()
    return

